#!/usr/bin/env bash
set -euo pipefail
GSZ=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BK="$GSZ/.bak-step159-$TS"
echo "==> step159: on-site OTP/Link retrieval (#7 Phase 2)"
echo "    backup: $BK"
mkdir -p "$BK/lib" "$BK/routes" "$BK/views/account"
cp "$GSZ/lib/botapi.js"                    "$BK/lib/"           2>/dev/null || true
cp "$GSZ/routes/whatsapp.js"               "$BK/routes/"        2>/dev/null || true
cp "$GSZ/views/account/credentials.ejs"    "$BK/views/account/" 2>/dev/null || true

restore(){ echo "!! error — restoring"; cp "$BK/lib/botapi.js" "$GSZ/lib/" 2>/dev/null || true; cp "$BK/routes/whatsapp.js" "$GSZ/routes/" 2>/dev/null || true; cp "$BK/views/account/credentials.ejs" "$GSZ/views/account/" 2>/dev/null || true; }
trap 'restore' ERR

PATCHER=$(mktemp /tmp/patch_step159.XXXXXX.js)
echo "" | base64 -d > "$PATCHER"
echo "==> applying route/client patches"
NODE_PATH="$GSZ/node_modules" node "$PATCHER" "$GSZ"

echo "==> writing new credentials view"
VTMP=$(mktemp /tmp/credentials.XXXXXX.ejs)
echo "" | base64 -d > "$VTMP"
NODE_PATH="$GSZ/node_modules" node -e "const ejs=require('ejs'),fs=require('fs');ejs.compile(fs.readFileSync('$VTMP','utf8'),{filename:'$VTMP',compileDebug:false});console.log('    new credentials.ejs compiles')"
mv "$VTMP" "$GSZ/views/account/credentials.ejs"

echo "==> validating"
node --check "$GSZ/lib/botapi.js"
node --check "$GSZ/routes/whatsapp.js"
NODE_PATH="$GSZ/node_modules" node -e "const ejs=require('ejs'),fs=require('fs');ejs.compile(fs.readFileSync('$GSZ/views/account/credentials.ejs','utf8'),{filename:'$GSZ/views/account/credentials.ejs'});console.log('    ejs ok')"

echo "==> restarting"
pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
CODE=000
for i in $(seq 1 25); do sleep 1; CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || echo 000); [ "$CODE" = "200" ] && break; done
[ "$CODE" = "200" ] || { echo "    homepage $CODE after ${i}s"; false; }
echo "    homepage 200: OK (after ${i}s)"

rm -f "$PATCHER"
trap - ERR
echo ""
echo "==> step159 OK  Customers can now fetch their sign-in CODE / login LINK right on their order's credentials page (Account → order → View details). Buttons show only where the bot enables otp/link, the fetch is ownership-checked server-to-server, and it shares ONE limit with WhatsApp. delivery_note + warranty now show there too. #7 complete."
